allowedClaimsDebtDeltas.before:
componentDidMount(){ this._t=setInterval(()=>this.forceUpdate(),30000); }
componentWillUnmount(){ clearInterval(this._t); }
cd(){ const end=Date.UTC(2026,10,1,4,0,0); let ms=Math.max(0,end-Date.now()); const d=Math.floor(ms/864e5); ms-=d*864e5; const h=Math.floor(ms/36e5); ms-=h*36e5; const m=Math.floor(ms/6e4); const p=n=>String(n).padStart(2,'0'); return {d:String(d),h:p(h),m:p(m)}; }

.cd{display:flex;gap:10px;margin-top:22px;flex-wrap:wrap;align-items:center}
.cd .u{background:#0E161C;border:1px solid #2E3B45;border-radius:10px;padding:8px 12px;min-width:74px;text-align:center}
.cd .u b{display:block;font-size:28px;line-height:1.1;font-weight:800}
.cd .u span{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#A9B4BB;font-weight:700}
.cd .cl{font-size:15px;color:#C9D1D6;margin-left:4px}

allowedClaimsDebtDeltas.after:
@media (min-width:981px){.rgrid.four{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media (min-width:761px){.rgrid.ten{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (min-width:1200px){.rgrid.ten{grid-template-columns:repeat(5,minmax(0,1fr))}}
